import{_ as a,c as i,o as l,ah as n}from"./chunks/framework.BssxmkiH.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),r={name:"changelog.md"};function o(t,e,d,s,h,c){return l(),i("div",null,e[0]||(e[0]=[n('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><h2 id="_2-6-4" tabindex="-1">2.6.4 <a class="header-anchor" href="#_2-6-4" aria-label="Permalink to “2.6.4”">​</a></h2><h3 id="fixed" tabindex="-1">FIXED <a class="header-anchor" href="#fixed" aria-label="Permalink to “FIXED”">​</a></h3><ul><li>Compilation errors on URP version 14.0 (Unity 6.0)</li><li>Placed demo scripts into their dedicated render pipeline unity packages.</li></ul><h2 id="_2-6-3" tabindex="-1">2.6.3 <a class="header-anchor" href="#_2-6-3" aria-label="Permalink to “2.6.3”">​</a></h2><h3 id="fixed-1" tabindex="-1">FIXED <a class="header-anchor" href="#fixed-1" aria-label="Permalink to “FIXED”">​</a></h3><ul><li>Fixed disabled features on Linux and other platforms after building player.</li><li>Removed FastSkySceneConfig game object auto-instancing.</li><li>Fixed half precision issues and general bugs.</li><li>Fixed RenderGraph error</li></ul><h3 id="improvements" tabindex="-1">IMPROVEMENTS <a class="header-anchor" href="#improvements" aria-label="Permalink to “IMPROVEMENTS”">​</a></h3><ul><li>Performance improvements.</li></ul><h3 id="improvement" tabindex="-1">IMPROVEMENT <a class="header-anchor" href="#improvement" aria-label="Permalink to “IMPROVEMENT”">​</a></h3><ul><li>Added the option to disable camera background type warning.</li></ul><h2 id="_2-6-2" tabindex="-1">2.6.2 <a class="header-anchor" href="#_2-6-2" aria-label="Permalink to “2.6.2”">​</a></h2><h3 id="fixed-2" tabindex="-1">FIXED <a class="header-anchor" href="#fixed-2" aria-label="Permalink to “FIXED”">​</a></h3><ul><li>Type error when using the IL2CPP scripting backend.</li><li>Instantaneous 180-degree flip as the moon passes through the zenith when astronomical positioning is disabled.</li></ul><h3 id="new" tabindex="-1">NEW <a class="header-anchor" href="#new" aria-label="Permalink to “NEW”">​</a></h3><ul><li>Removed moon orientation. This is now specified by the z-axis of the moon transform&#39;s rotation.</li></ul><h2 id="_2-6-1" tabindex="-1">2.6.1 <a class="header-anchor" href="#_2-6-1" aria-label="Permalink to “2.6.1”">​</a></h2><h3 id="fixed-3" tabindex="-1">FIXED <a class="header-anchor" href="#fixed-3" aria-label="Permalink to “FIXED”">​</a></h3><ul><li>Fixed skymap settings not showing up in the editor.</li><li>Fixed moon rotation gimbal-locking on Astronomical Positioning.</li><li>Unecessary debug log on Built-in RenderPipeline.</li></ul><h3 id="improvements-1" tabindex="-1">IMPROVEMENTS <a class="header-anchor" href="#improvements-1" aria-label="Permalink to “IMPROVEMENTS”">​</a></h3><ul><li>Improved moon occulusion. The non-lit face of the moon now occuldes stars and skymaps, preventing them from bleeding through the moon.</li><li>Improved URP demo scenes and settings.</li></ul><h2 id="_2-6-0" tabindex="-1">2.6.0 <a class="header-anchor" href="#_2-6-0" aria-label="Permalink to “2.6.0”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>VERSION 2.6.0 HAD A MAJOR PROJECT STRUCTURE CHANGE. ENSURE TO DELETE OLD PACKAGE FILES BEFORE IMPORTING THIS ONE.</p></div><h3 id="new-1" tabindex="-1">NEW <a class="header-anchor" href="#new-1" aria-label="Permalink to “NEW”">​</a></h3><ul><li>Added VR Support</li><li>Added support for Built-in Render Pipeline</li><li>Added astronomical positioning mode for celestial bodies (moon and sun) based on a specified time of day / time of year using earth&#39;s orbital model.</li><li>Added atmospheric height fog (aerial perspective).</li><li>Added skymap rotation.</li><li>Added earth curvature, simulating the look of observing from an elevated height, giving the earth a curved look.</li></ul><h3 id="improvements-2" tabindex="-1">IMPROVEMENTS <a class="header-anchor" href="#improvements-2" aria-label="Permalink to “IMPROVEMENTS”">​</a></h3><ul><li>Cloud shadow tiling.</li><li>Enhanced moon rendering</li></ul><h3 id="fixed-4" tabindex="-1">FIXED <a class="header-anchor" href="#fixed-4" aria-label="Permalink to “FIXED”">​</a></h3><ul><li>Fixed shader compilation error on some platforms</li><li>Fixed errors on newer versions of Unity and extended compatability support to range from Unity 2021.3 to Unity 6.5</li><li>Fixed moon varying brightness, inconsistent rotation and shaping issues.</li><li>Fixed errors while loading presets on Unity 2021.3 - Unity 2022.3</li><li>Fixed other bugs</li></ul><h2 id="_2-0-1" tabindex="-1">2.0.1 <a class="header-anchor" href="#_2-0-1" aria-label="Permalink to “2.0.1”">​</a></h2><h3 id="new-2" tabindex="-1">NEW <a class="header-anchor" href="#new-2" aria-label="Permalink to “NEW”">​</a></h3><ul><li>Added silver lining effect.</li></ul><h3 id="fixed-5" tabindex="-1">FIXED <a class="header-anchor" href="#fixed-5" aria-label="Permalink to “FIXED”">​</a></h3><ul><li>Potential vunerabilities causing crashed on some platforms</li></ul><h3 id="improvement-1" tabindex="-1">IMPROVEMENT <a class="header-anchor" href="#improvement-1" aria-label="Permalink to “IMPROVEMENT”">​</a></h3><ul><li>Curvature property no longer causes stretching artifacts at values &gt; 0.5 when 3DSampling is disabled, thus 3DSampling is removed. (Minor breaking change)</li></ul><h2 id="_2-0-0" tabindex="-1">2.0.0 <a class="header-anchor" href="#_2-0-0" aria-label="Permalink to “2.0.0”">​</a></h2><p>Initial Release</p>',38)]))}const u=a(r,[["render",o]]);export{p as __pageData,u as default};
